if('IntersectionObserver' in window&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');entry.target.classList.remove('waiting');observer.unobserve(entry.target);setTimeout(()=>entry.target.style.setProperty('--reveal-delay','0ms'),950);}})},{threshold:.08});document.querySelectorAll('.service,.why-card,.person,.client-panel,.step').forEach(el=>{const siblings=[...el.parentElement.children].filter(x=>x.matches('.service,.why-card,.person,.client-panel,.step'));el.style.setProperty('--reveal-delay',Math.min(siblings.indexOf(el)%3,2)*85+'ms');el.classList.add('scroll-reveal');if(el.getBoundingClientRect().top>window.innerHeight*.9){el.classList.add('waiting');observer.observe(el);}else{el.classList.add('visible');el.style.setProperty('--reveal-delay','0ms');}});}
