const navigationLinks=[...document.querySelectorAll('nav a[href^="#"]')];const trackedSections=navigationLinks.map(a=>document.querySelector(a.getAttribute('href'))).filter(Boolean);let scrollQueued=false;
function positionNavIndicator(){const nav=document.getElementById('navigation'),line=nav.querySelector('.nav-active-line'),active=nav.querySelector('a[aria-current="location"]');if(!line)return;if(!active||window.matchMedia('(max-width:760px)').matches){line.style.opacity='0';return;}line.style.width=active.offsetWidth+'px';line.style.transform='translateX('+active.offsetLeft+'px)';line.style.opacity='1';}
document.addEventListener('nova-language',()=>requestAnimationFrame(positionNavIndicator));document.fonts?.ready.then(positionNavIndicator);
function updateNavigation(){const y=window.scrollY+160;let current=null;trackedSections.forEach(section=>{if(section.offsetTop<=y)current=section.id;});navigationLinks.forEach(a=>{if(a.getAttribute('href')==='#'+current)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});positionNavIndicator();const total=document.documentElement.scrollHeight-window.innerHeight;document.querySelector('.page-progress').style.transform='scaleX('+(total>0?Math.min(1,window.scrollY/total):0)+')';scrollQueued=false;}
window.addEventListener('scroll',()=>{if(!scrollQueued){scrollQueued=true;requestAnimationFrame(updateNavigation);}},{passive:true});window.addEventListener('resize',updateNavigation);window.addEventListener('load',updateNavigation);updateNavigation();


