const requiredBriefFields=[...form.querySelectorAll('[required]')];function validateBriefField(field){const es=language==='es';let error='';if(!field.value.trim())error=es?'Completá este campo.':'Please complete this field.';else if(field.type==='email'&&field.validity.typeMismatch)error=es?'Ingresá un correo válido, por ejemplo nombre@empresa.com.':'Enter a valid email, for example name@company.com.';else if(field.name==='message'&&field.value.trim().length<10)error=es?'Contanos un poco más: al menos 10 caracteres.':'Tell us a little more: at least 10 characters.';else if(!field.validity.valid)error=es?'Revisá el contenido de este campo.':'Please check this field.';document.getElementById('error-'+field.name).textContent=error;field.setAttribute('aria-invalid',String(!!error));return !error;}
